#!/usr/bin/env python3
from __future__ import annotations

import argparse
import concurrent.futures as cf
import dataclasses
import json
import os
import pathlib
import shutil
import subprocess
import sys
import time
from typing import Iterable


@dataclasses.dataclass(frozen=True)
class Job:
    degree: int
    prime: int
    linearmode: str
    collision: bool


def find_singular() -> str:
    for name in ("Singular", "singular"):
        path = shutil.which(name)
        if path:
            return path
    raise FileNotFoundError(
        "Singular was not found. Install it and make `Singular` or `singular` available on PATH."
    )


def monomials_upto_degree(d: int) -> list[tuple[int, int]]:
    return [(i, j) for total in range(d + 1) for i in range(total + 1) for j in [total - i]]


def singular_poly(varx: str, vary: str, coeffs: dict[tuple[int, int], str], d: int) -> str:
    terms: list[str] = []
    for i, j in monomials_upto_degree(d):
        if (i, j) in ((0, 0), (1, 0), (0, 1)):
            continue
        c = coeffs[(i, j)]
        mon = ""
        if i:
            mon += varx if i == 1 else f"{varx}^{i}"
        if j:
            mon += vary if j == 1 else f"{vary}^{j}"
        terms.append(f"{c}*{mon}" if mon else c)
    return " + ".join(terms) if terms else "0"


def coefficient_map(d: int, mode: str) -> tuple[str, str, list[str]]:
    mons = monomials_upto_degree(d)
    vars_all: list[str] = []
    A: dict[tuple[int, int], str] = {}
    B: dict[tuple[int, int], str] = {}
    n = 0
    for ij in mons:
        if ij in ((0, 0), (1, 0), (0, 1)):
            continue
        A[ij] = f"a{n}"
        vars_all.append(A[ij])
        n += 1
    for ij in mons:
        if ij in ((0, 0), (1, 0), (0, 1)):
            continue
        B[ij] = f"b{n}"
        vars_all.append(B[ij])
        n += 1
    P1 = singular_poly("x", "y", A, d)
    P2 = singular_poly("x", "y", B, d)
    if mode == "identity":
        F1 = f"x + ({P1})"
        F2 = f"y + ({P2})"
    elif mode == "swap":
        F1 = f"y + ({P1})"
        F2 = f"-x + ({P2})"
    else:
        raise ValueError("mode")
    return F1, F2, vars_all


def add_poly(p: dict[tuple[int, int], list[str]], key: tuple[int, int], term: str) -> None:
    p.setdefault(key, []).append(term)


def differentiate_poly(poly: dict[tuple[int, int], list[str]], axis: str) -> dict[tuple[int, int], list[str]]:
    out: dict[tuple[int, int], list[str]] = {}
    for i, j, terms in poly.items():
        exponent = i if axis == "x" else j
        if exponent == 0:
            continue
        key = (i - 1, j) if axis == "x" else (i, j - 1)
        for term in terms:
            add_poly(out, key, f"{exponent}*({term})")
    return out


def multiply_poly(p: dict[tuple[int, int], list[str]], q: dict[tuple[int, int], list[str]]) -> dict[tuple[int, int], list[str]]:
    out: dict[tuple[int, int], list[str]] = {}
    for i, j, pterms in p.items():
        for k, l, qterms in q.items():
            for a in pterms:
                for b in qterms:
                    add_poly(out, (i + k, j + l), f"({a})*({b})")
    return out


def subtract_poly(p: dict[tuple[int, int], list[str]], q: dict[tuple[int, int], list[str]]) -> dict[tuple[int, int], list[str]]:
    out: dict[tuple[int, int], list[str]] = {}
    for key, value in p.items():
        for term in value:
            add_poly(out, key, term)
    for key, terms in q.items():
        for term in terms:
            add_poly(out, key, f"-({term})")
    return out


def jacobian_coefficient_equations(d: int, mode: str) -> list[str]:
    mons = monomials_upto_degree(d)
    A: dict[tuple[int, int], list[str]] = {}
    B: dict[tuple[int, int], list[str]] = {}
    n = 0
    for ij in mons:
        if ij in ((0, 0), (1, 0), (0, 1)):
            continue
        add_poly(A, ij, f"a{n}")
        n += 1
    for ij in mons:
        if ij in ((0, 0), (1, 0), (0, 1)):
            continue
        add_poly(B, ij, f"b{n}")
        n += 1
    if mode == "identity":
        add_poly(A, (1, 0), "1")
        add_poly(B, (0, 1), "1")
    elif mode == "swap":
        add_poly(A, (0, 1), "1")
        add_poly(B, (1, 0), "-1")
    else:
        raise ValueError("mode")
    det = subtract_poly(
        multiply_poly(differentiate_poly(A, "x"), differentiate_poly(B, "y")),
        multiply_poly(differentiate_poly(A, "y"), differentiate_poly(B, "x")),
    )
    add_poly(det, (0, 0), "-1")
    return [key for key in sorted(det, key=lambda k: (k[0] + k[1], k[0], k[1]))]


def ideal_literal(equations: list[str]) -> str:
    return ",".join(equations)


def singular_script(job: Job) -> str:
    d, p, mode = job.degree, job.prime, job.linearmode
    F1, F2, coeffvars = coefficient_map(d, mode)
    jaceqs = ideal_literal(jacobian_coefficient_equations(d, mode))
    coefflist = ",".join(coeffvars)
    coeffring = f"{coefflist}," if coefflist else ""
    collision_block = ""
    if job.collision:
        collision_block = """
ring R2 = (p), (s,t,u,v,x,y), dp;
poly F1c = F1;
poly F2c = F2;
poly F1u = subst(subst(F1c,x,u),y,v);
poly F2u = subst(subst(F2c,x,u),y,v);
poly DETc = diff(F1c,x)*diff(F2c,y) - diff(F1c,y)*diff(F2c,x);
ideal Jc = {jaceqs};
ideal K = F1u-F1c, F2u-F2c, s*u - x*t - v*y - 1;
ideal G = std(Jc + K);
option(redSB);
print("COLLISIONGBSIZE");
print(size(G));
print("COLLISIONDIMENSION");
print(dim(G));
quit;
""".strip()
    return f"""
option(redSB);
ring Rp = (p), (x,y,{coeffring}), dp;
poly F1 = {F1};
poly F2 = {F2};
poly DET = diff(F1,x)*diff(F2,y) - diff(F1,y)*diff(F2,x);
ideal J = {jaceqs};
ideal G = std(J);
print("JACOBIANGENERATORCOUNT");
print(ncols(J));
print("JACOBIANGBSIZE");
print(size(G));
print("JACOBIANDIMENSION");
print(dim(G));
{collision_block}
quit;
""".strip()


def run_job(args: tuple[Job, str, str, int]) -> dict:
    job, singular, outroot, timeout = args
    tag = f"d{job.degree}_p{job.prime}_m{job.linearmode}_c{int(job.collision)}"
    work = pathlib.Path(outroot) / tag
    work.mkdir(parents=True, exist_ok=True)
    scriptpath = work / "job.sing"
    outputpath = work / "job.out"
    scriptpath.write_text(singular_script(job), encoding="utf-8")
    started = time.time()
    try:
        proc = subprocess.run(
            [singular, "-q", str(scriptpath)],
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            timeout=timeout,
            check=False,
        )
        status = "completed" if proc.returncode == 0 else "failed"
        code = proc.returncode
        output = proc.stdout
    except subprocess.TimeoutExpired as exc:
        status = "timeout"
        code = None
        output = exc.stdout or ""
    outputpath.write_text(output, encoding="utf-8", errors="replace")
    record = {
        "tag": tag,
        "degree": job.degree,
        "prime": job.prime,
        "linearmode": job.linearmode,
        "collision": job.collision,
        "status": status,
        "returncode": code,
        "seconds": round(time.time() - started, 3),
        "script": str(scriptpath),
        "output": str(outputpath),
        "contains_unit_ideal": "1" in output or "ideal" in output,
        "contains_collision_dimension": "COLLISIONDIMENSION" in output,
    }
    return record


def parse_args() -> argparse.Namespace:
    ap = argparse.ArgumentParser()
    ap.add_argument("--degrees", nargs="+", type=int, default=[2, 3])
    ap.add_argument("--primes", nargs="+", type=int, default=[101, 103, 107])
    ap.add_argument("--modes", nargs="+", choices=["identity", "swap"], default=["identity"])
    ap.add_argument("--workers", type=int, default=max(1, (os.cpu_count() or 2) - 1))
    ap.add_argument("--timeout", type=int, default=900)
    ap.add_argument("--out", default="keller_async_runs")
    ap.add_argument("--no-collision", action="store_true")
    return ap.parse_args()


def main() -> int:
    args = parse_args()
    singular = find_singular()
    outroot = pathlib.Path(args.out).resolve()
    outroot.mkdir(parents=True, exist_ok=True)
    jobs = [
        Job(d, p, mode, not args.no_collision)
        for d in args.degrees
        for p in args.primes
        for mode in args.modes
    ]
    print(f"Singular: {singular}")
    print(f"Jobs: {len(jobs)}  workers: {args.workers}  timeout/job: {args.timeout}")
    records: list[dict] = []
    with cf.ProcessPoolExecutor(max_workers=args.workers) as pool:
        futures = [pool.submit(run_job, (job, singular, str(outroot), args.timeout)) for job in jobs]
        for fut in cf.as_completed(futures):
            rec = fut.result()
            records.append(rec)
            print(json.dumps(rec, ensure_ascii=False), flush=True)
    records.sort(key=lambda r: r["tag"])
    summary = outroot / "summary.jsonl"
    with summary.open("w", encoding="utf-8") as f:
        for rec in records:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")
    print(f"Summary: {summary}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
